class Solution:
    def maxOperations(self, nums: List[int]) -> int:
        target = nums[0] + nums[1]
        i, cnt = 2, 1
        while i + 1 < len(nums) and nums[i] + nums[i + 1] == target:
            cnt += 1
            i += 2
        return cnt

