class Solution {
public:
    int maxOperations(vector<int>& nums) {
        int target = nums[0] + nums[1], cnt = 1;
        for (int i = 2; i + 1 < (int)nums.size(); i += 2)
            if (nums[i] + nums[i + 1] == target) cnt++; else break;
        return cnt;
    }
};

