class Solution:
    def maxOperations(self, nums: List[int]) -> int:
        n = len(nums)
        best = 0
        for s in set(nums[i] + nums[i + 1] for i in range(n - 1)):
            cnt, i = 0, 0
            while i + 1 < n and nums[i] + nums[i + 1] == s:
                cnt += 1
                i += 2
            best = max(best, cnt)
        return best

