        int n = nums.size(), best = 0;
        unordered_set<int> cand;
        for (int i = 0; i + 1 < n; i++) cand.insert(nums[i] + nums[i + 1]);
        for (int s : cand) {
            int cnt = 0;
            for (int i = 0; i + 1 < n; i += 2) {
                if (nums[i] + nums[i + 1] == s) cnt++; else break;
            }
            best = max(best, cnt);
        }
        return best;
    }
};

